-- ── GPU selection (gaming) ─────────────────────────────────────────────
-- This is a hybrid laptop: Intel UHD (00:02.0) + RTX 3070 Mobile (01:00.0).
-- HDMI-A-2 — the 1440p144 ASUS VG27WQ — is wired to the *NVIDIA* card, but
-- aquamarine picks the iGPU as primary by default. The log then shows
-- "GBM: Buffer is marked as multigpu, forcing linear": every frame for that
-- monitor is composited on Intel and copied to NVIDIA through an untiled
-- buffer. At 2560x1440@144 that copy is exactly the wrong thing to be doing.
--
-- Listing the dGPU first makes it the primary renderer, so frames are drawn
-- on the card the monitor is attached to and scanned out directly.
--
-- AQ_DRM_DEVICES is a COLON-separated list, and PCI paths contain colons.
-- Passing /dev/dri/by-path/pci-0000:01:00.0-card directly gets split into
-- "/dev/dri/by-path/pci-0000", "01" and "00.0-card" -- aquamarine then logs
-- "Found no gpus to use, cannot continue" and the session never starts.
-- (That is exactly what happened here once already.)
--
-- So: resolve by-path to /dev/dri/cardN at config-parse time. That keeps the
-- stability of by-path — cardN numbering is not guaranteed across reboots —
-- while handing aquamarine a string with no colons in the names.
--
-- The guard is deliberately strict: unless BOTH cards resolve to a plain
-- /dev/dri/cardN, the variable is left unset and Hyprland picks its own
-- default. A bad value here costs you the whole session, so failing closed
-- is the only sane behaviour.
--
-- TRADE-OFF: the desktop then renders on the dGPU, which costs battery.
-- Set gpuPreferDedicated to false below to go back to the iGPU for travel.
local gpuPreferDedicated = true

local function drmCardFor(pci)
    local f = io.popen("readlink -f /dev/dri/by-path/pci-" .. pci .. "-card 2>/dev/null")
    if not f then return nil end
    local path = f:read("l")
    f:close()
    if not path or not path:match("^/dev/dri/card%d+$") then return nil end
    return path
end

if gpuPreferDedicated then
    local dgpu = drmCardFor("0000:01:00.0")   -- RTX 3070, drives HDMI-A-2
    local igpu = drmCardFor("0000:00:02.0")   -- Intel UHD, drives eDP-1
    if dgpu and igpu then
        hl.env("AQ_DRM_DEVICES", dgpu .. ":" .. igpu)
    else
        io.stderr:write("hyprland.lua: GPU paths did not resolve; " ..
                        "leaving AQ_DRM_DEVICES unset\n")
    end
end

-- Let games and Steam target the dGPU explicitly.
hl.env("__NV_PRIME_RENDER_OFFLOAD", "1")
hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
hl.env("LIBVA_DRIVER_NAME", "nvidia")
hl.env("NVD_BACKEND", "direct")

