-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
-- Styling (gaps, borders, rounding, blur, shadow) comes from the active rice
-- at ~/.config/themes/current/hypr.lua; behaviour stays here. Switching a
-- profile repoints that symlink and runs `hyprctl reload`, which re-runs this
-- file and picks up the new values.
--
-- pcall'd on purpose: a broken or dangling theme must not take the whole
-- config down with it. Worst case we fall back to Hyprland's own defaults
-- and the session still comes up.
local themePath = os.getenv("HOME") .. "/.config/themes/current/hypr.lua"
local themeOk, theme = pcall(dofile, themePath)
if not themeOk or type(theme) ~= "table" then
    io.stderr:write("hyprland.lua: could not load theme " .. themePath .. "\n")
    theme = {}
end

local function withTheme(behaviour, styling)
    local out = {}
    for k, v in pairs(behaviour) do out[k] = v end
    for k, v in pairs(styling or {}) do out[k] = v end
    return out
end

hl.config({
    general = withTheme({
        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Tearing is opt-in per window, not global: enabling it here only
        -- permits it, and nothing tears until a window carries the
        -- `immediate` rule. The game rules further down set that, so this
        -- buys lower input latency in fullscreen games and changes nothing
        -- anywhere else.
        -- https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/
        allow_tearing = true,

        layout = "dwindle",
    }, theme.general),

    decoration = withTheme({}, theme.decoration),

    animations = {
        enabled = true,
    },
})

-- Motion is part of the rice, not a constant: a glassy theme wants long
-- eased fades, a CRT theme wants everything to snap. Each profile ships its
-- own curves + animation table in themes/current/hypr.lua, applied here.
-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/
--
-- A theme that omits either falls back to the stock set below, so an
-- animation-less theme file is still valid.

local defaultCurves = {
    { name = "easeOutQuint",   type = "bezier", points = { {0.23, 1},    {0.32, 1}    } },
    { name = "easeInOutCubic", type = "bezier", points = { {0.65, 0.05}, {0.36, 1}    } },
    { name = "linear",         type = "bezier", points = { {0, 0},       {1, 1}       } },
    { name = "almostLinear",   type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } },
    { name = "quick",          type = "bezier", points = { {0.15, 0},    {0.1, 1}     } },
    { name = "easy",           type = "spring", mass = 1, stiffness = 238.1191, dampening = 24.21279333 },
}

local defaultAnimations = {
    { leaf = "global",        enabled = true, speed = 10,   bezier = "default" },
    { leaf = "border",        enabled = true, speed = 5.39, bezier = "easeOutQuint" },
    { leaf = "windows",       enabled = true, speed = 4.79, spring = "easy" },
    { leaf = "windowsIn",     enabled = true, speed = 4.1,  spring = "easy",         style = "popin 87%" },
    { leaf = "windowsOut",    enabled = true, speed = 1.49, bezier = "linear",       style = "popin 87%" },
    { leaf = "fadeIn",        enabled = true, speed = 1.73, bezier = "almostLinear" },
    { leaf = "fadeOut",       enabled = true, speed = 1.46, bezier = "almostLinear" },
    { leaf = "fade",          enabled = true, speed = 3.03, bezier = "quick" },
    { leaf = "layers",        enabled = true, speed = 3.81, bezier = "easeOutQuint" },
    { leaf = "layersIn",      enabled = true, speed = 4,    bezier = "easeOutQuint", style = "fade" },
    { leaf = "layersOut",     enabled = true, speed = 1.5,  bezier = "linear",       style = "fade" },
    { leaf = "fadeLayersIn",  enabled = true, speed = 1.79, bezier = "almostLinear" },
    { leaf = "fadeLayersOut", enabled = true, speed = 1.39, bezier = "almostLinear" },
    { leaf = "workspaces",    enabled = true, speed = 1.94, bezier = "almostLinear", style = "fade" },
    { leaf = "workspacesIn",  enabled = true, speed = 1.21, bezier = "almostLinear", style = "fade" },
    { leaf = "workspacesOut", enabled = true, speed = 1.94, bezier = "almostLinear", style = "fade" },
    { leaf = "zoomFactor",    enabled = true, speed = 7,    bezier = "quick" },
}

for _, c in ipairs(theme.curves or defaultCurves) do
    if c.type == "spring" then
        hl.curve(c.name, { type = "spring", mass = c.mass,
                           stiffness = c.stiffness, dampening = c.dampening })
    else
        hl.curve(c.name, { type = "bezier", points = c.points })
    end
end

for _, a in ipairs(theme.animations or defaultAnimations) do
    hl.animation(a)
end

