-- ── Games ──────────────────────────────────────────────────────────────
-- Every rice sets blur, shadows, rounding, opacity and animations. None of
-- that should be running over a fullscreen game: it costs GPU time on the
-- same card that is trying to hold 144fps, and rounding on a fullscreen
-- window is invisible anyway. These rules strip the compositor back to a
-- plain scanout for games regardless of which profile is active.
--
-- `immediate` is what actually enables tearing (general.allow_tearing only
-- permits it) — it lets a finished frame be scanned out mid-refresh instead
-- of waiting, which is the latency win.
hl.window_rule({
    name  = "games-no-effects",
    match = { fullscreen = true },

    no_blur   = true,
    no_shadow = true,
    no_anim   = true,
    rounding  = 0,
    immediate = true,
})

-- Steam's own chrome: the client, the overlay and the big-picture window
-- float badly by default and pick up the rice's blur for no benefit.
hl.window_rule({
    name  = "steam-client",
    match = { class = "^steam$" },

    no_blur = true,
})

hl.window_rule({
    -- Steam's notification/overlay popups have no title and misbehave when
    -- tiled; float them and keep focus on the game.
    name  = "steam-popups",
    match = { class = "^steam$", title = "^$" },

    float    = true,
    no_focus = true,
})

-- mako toasts — blur behind the translucent pill so they read the same
-- as waybar's islands over a busy wallpaper. ignore_alpha skips the fully
-- transparent gaps between stacked notifications, which would otherwise
-- render as blurred rectangles.
hl.layer_rule({
    name  = "blur-notifications",
    match = { namespace = "^notifications$" },

    blur         = true,
    ignore_alpha = 0.5,
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- nmtui, launched from the waybar network module — float it as a panel
-- under the bar instead of tiling into the workspace.
hl.window_rule({
    name  = "float-nm-tui",
    match = { class = "nm-float" },

    float = true,
    size  = "620 420",
    move  = "monitor_w-640 40",
})
